import{_ as e,o as a,c as o,X as i}from"./chunks/framework.92e7fb7b.js";const m=JSON.parse('{"title":"backend interview questions","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/coding-learning-record/backend-interview.md","filePath":"blogs/coding-learning-record/backend-interview.md"}'),r={name:"blogs/coding-learning-record/backend-interview.md"},t=i('<h1 id="backend-interview-questions" tabindex="-1">backend interview questions <a class="header-anchor" href="#backend-interview-questions" aria-label="Permalink to &quot;backend interview questions&quot;">​</a></h1><h2 id="自定义线程池" tabindex="-1">自定义线程池 <a class="header-anchor" href="#自定义线程池" aria-label="Permalink to &quot;自定义线程池&quot;">​</a></h2><ol><li>核心线程数</li><li>最大线程数</li><li>工作队列</li></ol><p>在一个电商平台的后端系统中，假设我们需要设计一个用于处理订单的自定义线程池。核心线程数、最大线程数和工作队列的设计时需要注意</p><h3 id="业务场景" tabindex="-1">业务场景： <a class="header-anchor" href="#业务场景" aria-label="Permalink to &quot;业务场景：&quot;">​</a></h3><ul><li><strong>核心业务场景</strong>：处理订单请求，包括验证订单信息、扣除库存、生成订单号等。</li><li><strong>技术栈</strong>：Java后端开发，Spring框架。</li><li><strong>核心实现</strong>：自定义线程池用于管理订单处理的并发执行。</li><li><strong>重点难点</strong>：保证订单处理的高并发和可靠性，避免资源竞争和订单丢失。</li></ul><h3 id="核心线程数-core-pool-size" tabindex="-1">核心线程数（Core Pool Size）： <a class="header-anchor" href="#核心线程数-core-pool-size" aria-label="Permalink to &quot;核心线程数（Core Pool Size）：&quot;">​</a></h3><ul><li><strong>业务场景关联</strong>：核心线程数应该根据订单的日均请求量和处理时间来确定。对于一个电商平台，订单请求可能会呈现出明显的日周期性波动，因此核心线程数应该足够以应对峰值时段的订单处理需求，同时避免过多的线程闲置。</li><li><strong>技术实现</strong>：在Spring框架中，可以使用ThreadPoolTaskExecutor来创建自定义线程池，并通过设置corePoolSize属性来指定核心线程数。</li><li><strong>难点解决</strong>：通过监控订单请求量和系统资源利用率，动态调整核心线程数以适应业务需求的变化。</li></ul><h3 id="最大线程数-maximum-pool-size" tabindex="-1">最大线程数（Maximum Pool Size）： <a class="header-anchor" href="#最大线程数-maximum-pool-size" aria-label="Permalink to &quot;最大线程数（Maximum Pool Size）：&quot;">​</a></h3><ul><li><strong>业务场景关联</strong>：最大线程数应该根据系统的资源限制和预期的最大并发量来确定。在电商平台中，最大线程数的设置应该考虑服务器的CPU和内存资源，以及数据库连接池等外部资源的限制。</li><li><strong>技术实现</strong>：在ThreadPoolTaskExecutor中，可以通过设置maxPoolSize属性来指定最大线程数。</li><li><strong>难点解决</strong>：避免因线程过多而导致资源竞争或内存溢出的问题，需要通过压力测试和性能调优来确定合适的最大线程数。</li></ul><h3 id="工作队列-work-queue" tabindex="-1">工作队列（Work Queue）： <a class="header-anchor" href="#工作队列-work-queue" aria-label="Permalink to &quot;工作队列（Work Queue）：&quot;">​</a></h3><ul><li><strong>业务场景关联</strong>：工作队列用于存储尚未被执行的订单处理任务，应该能够满足高并发请求下的任务排队需求。在电商平台中，可以选择一个适当大小的有界队列来限制订单处理的并发量，以防止系统资源被无限制地占用。</li><li><strong>技术实现</strong>：在ThreadPoolTaskExecutor中，可以通过设置queueCapacity属性来指定工作队列的大小。</li><li><strong>难点解决</strong>：避免因队列溢出而导致的订单丢失或系统性能下降，需要根据系统负载和任务处理时间来动态调整工作队列的大小，并采取适当的任务拒绝策略。</li></ul><p>通过以上的结构化设计考量，可以设计出一个高效、稳定的订单处理线程池，以满足业务需求的高并发和可靠性要求。</p><h2 id="osi-七层模型是什么样的" tabindex="-1">OSI 七层模型是什么样的 <a class="header-anchor" href="#osi-七层模型是什么样的" aria-label="Permalink to &quot;OSI 七层模型是什么样的&quot;">​</a></h2><p>路由器工作在哪一层？</p><h2 id="tcp-如何保证可靠连接-tcp-如何建立可靠的连接-三次握手的详细过程" tabindex="-1">TCP 如何保证可靠连接？TCP 如何建立可靠的连接？三次握手的详细过程 <a class="header-anchor" href="#tcp-如何保证可靠连接-tcp-如何建立可靠的连接-三次握手的详细过程" aria-label="Permalink to &quot;TCP 如何保证可靠连接？TCP 如何建立可靠的连接？三次握手的详细过程&quot;">​</a></h2><h2 id="effective-java-要点" tabindex="-1">Effective Java 要点 <a class="header-anchor" href="#effective-java-要点" aria-label="Permalink to &quot;Effective Java 要点&quot;">​</a></h2>',17),l=[t];function n(s,c,d,h,u,g){return a(),o("div",null,l)}const p=e(r,[["render",n]]);export{m as __pageData,p as default};
